nta.declaration:
// Powertrain air-fuel-ratio control
const double DT = 0.05;
const double BOUND = 50.0;
const double AFR_LOW = 14.3;
const double AFR_HIGH = 15.1;
const double AFR_TARGET = 14.7;

clock t;
hybrid clock afr = 14.7;
hybrid clock throttle = 10.0;
hybrid clock ceff = 0.8;
bool started = false;
bool failed = false;

double dmin(double x, double y) { return x < y ? x : y; }
double demand(double tt) { return 40.0 + 25.0 * sin(tt * 0.6) + 10.0 * sin(tt * 1.5); }
double margin(double v) { return dmin(v - AFR_LOW, AFR_HIGH - v); }

void step() {
    double dmd = demand(t);
    double dmag = fabs((dmd - throttle) * DT * 12.0) * 0.4;
    double dsign = random(1.0) < 0.5 ? -1.0 : 1.0;
    double noise = (random(1.0) - 0.5) * 0.15;
    double spike = random(1.0) < 0.01 ? (random(1.0) - 0.5) * 0.8 : 0.0;
    double na = afr + (ceff * 2.5 * (AFR_TARGET - afr) + dmag * dsign + spike) * DT + noise * sqrt(DT);
    double nr = margin(na);
    throttle = throttle + (dmd - throttle) * DT * 12.0;
    afr = afr + (ceff * 2.5 * (AFR_TARGET - afr) + dmag * dsign + spike) * DT + noise * sqrt(DT);
    if (nr < 0.0) failed = true;
}
